// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonAdmin) public {
        vm.assume(nonAdmin != address(this));
        vm.assume(nonAdmin != address(c));
        // admin is the deployer of setUp (i.e., this contract)
        vm.assume(nonAdmin != address(this)); // address(this) is admin
        // Ensure nonAdmin is restricted: it must NOT be the admin
        // The admin is msg.sender of the C constructor, which is the InvMutTest contract.
        // We verify that and exclude it.
        vm.assume(nonAdmin != address(this));

        address originalOwner = c.owner();

        vm.prank(nonAdmin);
        bool success = c.setOwner(nonAdmin);
        // In the reference, the call should revert because only admin can call.
        // However, a revert in a pranked call will cause the test to fail via forge's mechanism.
        // We use try-catch to observe revert without failing.
        // But we already called it; we need to capture the revert. We'll use a low-level call.
        vm.prank(nonAdmin);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", nonAdmin));
        // In reference: ok is false (revert); in bug: ok is true (success)
        // After the call, check owner changed only if call succeeded.
        address currentOwner = c.owner();

        // General rule: if the call was made by a non-admin, the owner must remain unchanged.
        // In the buggy version, the call succeeds and changes owner, breaking the rule.
        assertTrue(currentOwner == originalOwner);
    }
}

