import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Ensure caller is not admin and newOwner is not the current owner
        address originalAdmin = address(uint160(uint256(keccak256(abi.encodePacked(address(c), bytes32(uint256(0))))))); // admin is private, we don't know it directly
        // We don't have direct access to the private admin. But the rule targets any caller.
        // We can test the property: after a setOwner call, if caller != admin, owner should remain unchanged.
        // To check this, we need to know the initial admin. Since admin is set in constructor and is private,
        // we cannot read it. But we can fuzz caller and check behavior.
        // The rule: For any caller, after calling setOwner, owner changes to newOwner only if caller is admin.
        // If caller is not admin, owner must be unchanged. But we don't know admin. So we derive that
        // if the setOwner call does not revert, then caller must be admin. If it reverts, caller is not admin.
        // This is the property the bug breaks: the buggy version always succeeds.
        // So: Either the call reverts (caller != admin) or succeeds (caller == admin).
        // But a universal rule must hold for all inputs: after the call, owner is either the new owner (if caller is admin) or unchanged (if caller is not admin).
        // We can observe this without knowing admin by checking that if owner changed, the call must have succeeded.
        // But the bug breaks this: a non-admin caller can change owner without revert.
        // So the invariant: (owner after call != newOwner) OR (call succeeded).
        // In the correct contract, a non-admin caller cannot change owner, so owner stays as before.
        // In the buggy contract, a non-admin caller can change owner, so owner becomes newOwner and call succeeds, breaking the property that a non-admin cannot change owner.
        // More precisely: the property "if call succeeds, then owner == newOwner" holds for both. But we need a property that holds for reference and fails for bug.
        // The buggy one always succeeds, so "call succeeds" is true for all inputs. In reference, call succeeds only for admin.
        // So a property: if caller is not admin, owner must not change.
        // Since we don't know admin, we can check: if owner after call is different from owner before call, then the caller must be admin.
        // But still we can't assert directly on admin. Instead, we can bound the test to check that owner changes only if caller is a specific address that we can derive? No.
        // Alternative: the admin is the deployer of the contract. In setUp, we deploy c via `new C()`, so address(this) is the admin.
        // Yes, because C's constructor sets admin = payable(msg.sender), and setUp is called by the test contract (InvMutTest). So admin = address(this).
        // We can use vm.prank to simulate any caller.
        address admin = address(this);
        vm.assume(caller != admin);
        // We want to test a non-admin caller.
        address ownerBefore = c.owner();
        vm.prank(caller);
        c.setOwner(newOwner);
        // After the call, in the reference contract, owner should remain ownerBefore because onlyAdmin modifier would reject caller.
        // In the buggy version, the call succeeds and owner becomes newOwner.
        // So the invariant: if caller != admin, then c.owner() == ownerBefore.
        assertTrue(c.owner() == ownerBefore);
    }
}

