        c.setOwner(newOwner1);

        vm.prank(caller2);
        c.setOwner(newOwner2);

        // After the second call, the owner must equal newOwner2.
        // The reference contract allows only the admin to change the owner, so both calls are rejected
        // and owner remains the original admin. Thus owner != newOwner2 (unless newOwner2 happens to be the admin).
