    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(caller != admin);
        vm.prank(admin);
        c.setOwner(caller); // make caller the owner
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool) { ok = true; } catch { ok = false; }
        // In correct contract, ok must be false because caller is not admin.
        // In mutant, ok will be true because caller is owner.
        assertTrue(!ok, "Non-admin owner should not be able to call setOwner");
    }
